"""Select Native ending/continuing highway geometry comparison points."""

from math import hypot

from ending_road_route import _junction, _paths_from_spawn


def select_point(world_map, *, subject_continues, max_spawns=300):
    """Return one connected same-junction point with verified road continuity."""
    if type(subject_continues) is not bool:
        raise ValueError('Highway continuity choice must be boolean')
    routes = []
    for transform in world_map.get_spawn_points()[:max_spawns]:
        start = world_map.get_waypoint(transform.location)
        if start is None or start.is_junction:
            continue
        for path in _paths_from_spawn(start):
            entrance = next((point for point in path if point.is_junction), None)
            if entrance is not None:
                routes.append({'path': path, 'junction_id': _junction(entrance),
                               'road_id': path[0].road_id,
                               'selected_exit_continues': path[0].road_id == path[-1].road_id})
    continuous = {(route['junction_id'], route['road_id']) for route in routes
                  if route['selected_exit_continues']}
    for subject in routes:
        source_continues = (subject['junction_id'], subject['road_id']) in continuous
        if source_continues != subject_continues:
            continue
        # A continuing *approach* can also have a turning exit. The selected
        # comparison route must itself carry the same road beyond the junction.
        if subject_continues and not subject['selected_exit_continues']:
            continue
        for other in routes:
            if (other['junction_id'], other['road_id']) not in continuous or (
                    subject['junction_id'] != other['junction_id'] or
                    subject['road_id'] == other['road_id']):
                continue
            a = subject['path'][0].transform.get_forward_vector()
            b = other['path'][0].transform.get_forward_vector()
            length = hypot(a.x, a.y) * hypot(b.x, b.y)
            if length < 1e-6 or abs((a.x*b.x + a.y*b.y)/length) > .65:
                continue
            return {'subject': subject['path'], 'other': other['path'],
                    'junction_id': subject['junction_id'], 'map_name': world_map.name,
                    'subject_highway_continues': source_continues,
                    'other_highway_continues': True,
                    'selection_basis': 'all connected Native 2 m lane successors and distinct road identities',
                    'legal_highway_status_claimed': False}
    raise ValueError('No connected Native highway-continuity category point')


def select_controlled_pair(world_map, *, max_spawns=300, route_accept=None):
    """Find both subject categories at one junction with the same through route.

    The selected through path is the identical waypoint sequence for both points.
    The callback can reject controlled or otherwise unsuitable approach pairs.
    """
    routes = []
    for transform in world_map.get_spawn_points()[:max_spawns]:
        start = world_map.get_waypoint(transform.location)
        if start is None or start.is_junction:
            continue
        for path in _paths_from_spawn(start):
            entrance = next((point for point in path if point.is_junction), None)
            if entrance is not None:
                routes.append({'path': path, 'junction_id': _junction(entrance),
                               'road_id': path[0].road_id,
                               'continues': path[0].road_id == path[-1].road_id})
    continuous = {(r['junction_id'], r['road_id']) for r in routes if r['continues']}
    for other in routes:
        if not other['continues']:
            continue
        for ending in routes:
            if ((ending['junction_id'], ending['road_id']) in continuous or
                    ending['junction_id'] != other['junction_id'] or
                    ending['road_id'] == other['road_id']):
                continue
            for continuing in routes:
                if (not continuing['continues'] or
                        (continuing['junction_id'], continuing['road_id']) not in continuous or
                        continuing['junction_id'] != other['junction_id'] or
                        continuing['road_id'] in (other['road_id'], ending['road_id'])):
                    continue
                if not all(_transverse(r['path'][0], other['path'][0])
                           for r in (ending, continuing)):
                    continue
                if route_accept is not None and not all(
                        route_accept(r, other) for r in (ending, continuing)):
                    continue
                return {
                    'ending': ending['path'], 'continuing': continuing['path'],
                    'other': other['path'], 'junction_id': other['junction_id'],
                    'map_name': world_map.name,
                    'witness_paths': [route['path'] for route in routes
                                      if route['junction_id'] == other['junction_id'] and
                                      route['road_id'] in (ending['road_id'],
                                                           continuing['road_id'],
                                                           other['road_id'])],
                    'selection_basis': 'connected Native successors with one fixed through route',
                    'legal_highway_status_claimed': False,
                }
    raise ValueError('No controlled ending/continuing Native highway pair')


def _transverse(a, b):
    va = a.transform.get_forward_vector()
    vb = b.transform.get_forward_vector()
    length = hypot(va.x, va.y) * hypot(vb.x, vb.y)
    return length >= 1e-6 and abs((va.x * vb.x + va.y * vb.y) / length) <= .65

"""Find connected ending-road and through-road approaches in a Native map."""

from collections import deque
from math import hypot

def _junction(waypoint):
    return str(waypoint.get_junction().id) if waypoint.is_junction else None


def _key(waypoint):
    location = waypoint.transform.location
    return waypoint.road_id, waypoint.lane_id, round(location.x, 1), round(location.y, 1)


def _paths_from_spawn(start, *, max_approach=120, max_junction=35):
    """Yield connected exterior -> junction -> exterior paths, including branches."""
    current = start
    approach = [start]
    seen = set()
    for _ in range(max_approach):
        if _key(current) in seen:
            return
        seen.add(_key(current))
        forward = current.next(2.0)
        if not forward:
            return
        entrances = [point for point in forward if point.is_junction]
        if entrances:
            break
        current = next((point for point in forward if point.road_id == current.road_id),
                       forward[0])
        approach.append(current)
    else:
        return
    pending = deque(((approach + [entrance], 0, _junction(entrance)) for entrance in entrances))
    while pending:
        path, depth, junction_id = pending.popleft()
        if depth > max_junction:
            continue
        for successor in path[-1].next(2.0):
            if _key(successor) in {_key(point) for point in path}:
                continue
            candidate = path + [successor]
            if successor.is_junction:
                if _junction(successor) == junction_id:
                    pending.append((candidate, depth + 1, junction_id))
            else:
                yield candidate


def select_t_routes(world_map, *, max_spawns=300, route_accept=None):
    """Select one same-junction pair; reject ambiguous non-T lane continuity."""
    routes = []
    for transform in world_map.get_spawn_points()[:max_spawns]:
        start = world_map.get_waypoint(transform.location)
        if start is None or start.is_junction:
            continue
        for path in _paths_from_spawn(start):
            entrance = next(point for point in path if point.is_junction)
            exit_waypoint = path[-1]
            routes.append({'path': path,
                           'junction_id': _junction(entrance),
                           'approach_road_id': path[0].road_id,
                           'continues': path[0].road_id == exit_waypoint.road_id})
    # A selected turning branch cannot prove that a highway ends when another
    # connected branch of the same approach carries its road ID through.
    continuity = {(route['junction_id'], route['approach_road_id'])
                  for route in routes if route['continues']}
    for ending in routes:
        if (ending['junction_id'], ending['approach_road_id']) in continuity:
            continue
        for through in routes:
            if (not through['continues'] or
                    through['junction_id'] != ending['junction_id'] or
                    through['approach_road_id'] == ending['approach_road_id']):
                continue
            a = ending['path'][0].transform.get_forward_vector()
            b = through['path'][0].transform.get_forward_vector()
            length = hypot(a.x, a.y) * hypot(b.x, b.y)
            if length < 1e-6 or abs((a.x*b.x + a.y*b.y)/length) > .65:
                continue
            if route_accept is not None and not route_accept(ending, through):
                continue
            return {'subject': ending['path'], 'other': through['path'],
                    'junction_id': ending['junction_id'],
                    'map_name': world_map.name,
                    'selection_basis': 'connected Native 2 m lane successors, distinct OpenDRIVE road IDs and approximately transverse approaches',
                    'legal_highway_classification_claimed': False}
    raise ValueError('No connected ending-road/through-road T-junction approaches in Native map')

"""Retain original Native T-junction topology and participant body frames.

OpenDRIVE road IDs are operational topology keys. They do not establish a
legal highway classification or the statutory approximately-same-time test.
"""

from __future__ import annotations

import json
from math import atan2, hypot, isfinite
from pathlib import Path

from ending_road_measurement import classify_approaches


def _body(actor):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    points = sorted({(float(vertex.x), float(vertex.y)) for vertex in vertices})
    if len(points) != 4 or any(not all(isfinite(x) for x in point) for point in points):
        raise ValueError('Native participant needs four finite ground corners')
    cx = sum(x for x, _ in points) / 4
    cy = sum(y for _, y in points) / 4
    return [list(point) for point in sorted(points,
            key=lambda point: atan2(point[1] - cy, point[0] - cx))]


def _linked(first, second):
    target = second.transform.location
    for candidate in first.next(2.0):
        location = candidate.transform.location
        if (candidate.road_id, candidate.lane_id) == (second.road_id, second.lane_id) and hypot(
                location.x - target.x, location.y - target.y) < 0.75:
            return True
    return False


def _junction_id(waypoint):
    if not waypoint.is_junction:
        return None
    junction = waypoint.get_junction()
    if junction is None:
        raise ValueError('Native junction waypoint has no junction readback')
    return str(junction.id)


def _path_nodes(role, path, expected_junction):
    if len(path) < 3 or path[0].is_junction or path[-1].is_junction:
        raise ValueError('Native approach needs exterior, junction and exterior waypoints')
    ids = [f'{role}-{index}' for index in range(len(path))]
    nodes = {}
    seen_junction = False
    if any(not _linked(first, second) for first, second in zip(path, path[1:])):
        raise ValueError('Native route waypoints are not connected successors')
    for index, waypoint in enumerate(path):
        junction = _junction_id(waypoint)
        if junction is not None:
            seen_junction = True
            if junction != expected_junction:
                raise ValueError('Native paths enter different junctions')
        if waypoint.road_id is None or waypoint.lane_id is None:
            raise ValueError('Native waypoint lacks road or lane readback')
        nodes[ids[index]] = {'highway_id': 'native-road:' + str(waypoint.road_id),
                             'road_id': waypoint.road_id, 'lane_id': waypoint.lane_id,
                             'junction_id': junction,
                             'successors': [ids[index + 1]] if index + 1 < len(path) else []}
    if not seen_junction or path[-1].road_id == path[0].road_id and role == 'subject':
        raise ValueError('Subject path lacks an ending-road junction traversal')
    return ids[0], nodes


def topology_from_native(subject_path, other_path, subject_actor, other_actor,
                         junction, conflict_polygon_xy):
    junction_id = str(junction.id)
    subject, subject_nodes = _path_nodes('subject', subject_path, junction_id)
    other, other_nodes = _path_nodes('other', other_path, junction_id)
    nodes = {**subject_nodes, **other_nodes}
    if len(conflict_polygon_xy) < 3 or any(
            len(point) != 2 or not all(isfinite(float(x)) for x in point)
            for point in conflict_polygon_xy):
        raise ValueError('Native conflict zone polygon is missing or nonfinite')
    topology = {'format': 'worker-ending-road-original-topology',
                'highway_identity_source': 'Native OpenDRIVE road_id readback; operational continuity only',
                'junction_id': junction_id, 'lanes': nodes,
                'subject_approach_lane': subject, 'other_approach_lane': other,
                'subject_id': str(subject_actor.id), 'other_id': str(other_actor.id),
                'conflict_polygon_xy': [list(map(float, point)) for point in conflict_polygon_xy],
                'legal_highway_classification_claimed': False}
    classify_approaches(topology)
    return topology


class EndingRoadSourceRecorder:
    def __init__(self, output, topology, subject_actor, other_actor):
        self.output = Path(output)
        self.output.mkdir(parents=True, exist_ok=True)
        self.topology_path = self.output / 'intersection_topology.json'
        self.rows_path = self.output / 'intersection_participants.jsonl'
        if self.topology_path.exists() or self.rows_path.exists():
            raise FileExistsError('Retain prior original ending-road source')
        if topology['subject_id'] != str(subject_actor.id) or topology['other_id'] != str(other_actor.id):
            raise ValueError('Native actor identities differ from selected topology')
        classify_approaches(topology)
        self.subject = subject_actor
        self.other = other_actor
        self.topology_path.write_text(json.dumps(topology, indent=2, allow_nan=False) + '\n')
        self.stream = self.rows_path.open('x')
        self.previous = None

    def append(self, frame, time_s):
        if type(frame) is not int or not isfinite(time_s):
            raise ValueError('Original Native frame/time readback invalid')
        if self.previous is not None and (frame != self.previous[0] + 1 or
                                          abs(time_s - self.previous[1] - .05) > 1e-4):
            raise ValueError('Original Native ending-road source is not 20 Hz')
        row = {'frame': frame, 'time_s': time_s,
               'subject_id': str(self.subject.id), 'other_id': str(self.other.id),
               'subject_corners': _body(self.subject), 'other_corners': _body(self.other)}
        self.stream.write(json.dumps(row, allow_nan=False) + '\n')
        self.stream.flush()
        self.previous = frame, time_s
        return row

    def close(self):
        self.stream.close()

"""Measure a T-intersection entry comparison from retained Native-shaped sources.

Highway continuity comes from the retained lane graph and explicit highway
identity, not a scenario flag saying that the subject road ends.
"""

from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path


def _read(path, label):
    path = Path(path)
    if not path.is_file():
        raise ValueError("Missing required source: " + label)
    raw = path.read_bytes()
    if not raw:
        raise ValueError("Empty required source: " + label)
    try:
        return json.loads(raw), sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("Invalid required source: " + label) from error


def classify_approaches(topology):
    if not topology.get("highway_identity_source") or not topology.get("junction_id"):
        raise ValueError("Topology lacks highway identity or junction source")
    nodes = topology.get("lanes")
    if not isinstance(nodes, dict):
        raise ValueError("Topology lacks connected lane graph")
    selected = {}
    for role in ("subject", "other"):
        start = topology.get(role + "_approach_lane")
        if start not in nodes or nodes[start].get("junction_id") not in (None, topology["junction_id"]):
            raise ValueError("Selected approach does not enter the same junction")
        highway = nodes[start].get("highway_id")
        if not highway:
            raise ValueError("Approach lacks source-backed highway identity")
        outgoing = nodes[start].get("successors")
        if not isinstance(outgoing, list) or not outgoing:
            raise ValueError("Approach lacks a drivable junction successor")
        # Native maps commonly put one or more junction lanes between the
        # approach and the outgoing highway. Follow those lanes to the first
        # exterior lane rather than treating the junction waypoint as an exit.
        pending = list(outgoing)
        visited = set()
        exterior = []
        entered_junction = nodes[start].get("junction_id") == topology["junction_id"]
        while pending:
            successor = pending.pop()
            if successor not in nodes:
                raise ValueError("Lane successor is absent from topology")
            if successor in visited:
                continue
            visited.add(successor)
            lane = nodes[successor]
            if lane.get("junction_id") == topology["junction_id"]:
                entered_junction = True
                following = lane.get("successors")
                if not isinstance(following, list):
                    raise ValueError("Junction lane lacks source-backed successors")
                pending.extend(following)
            elif lane.get("junction_id") is None:
                if not entered_junction:
                    raise ValueError("Selected approach bypasses the same junction")
                exterior.append(successor)
            else:
                raise ValueError("Approach successor enters another junction")
        if not entered_junction or not exterior:
            raise ValueError("Approach has no source-backed exit beyond junction")
        same_highway_out = [successor for successor in exterior
                            if nodes[successor].get("highway_id") == highway]
        selected[role] = {"approach_lane": start, "highway_id": highway,
                          "continues_beyond_junction": bool(same_highway_out),
                          "successors": outgoing, "exterior_lanes": sorted(exterior)}
    if selected["subject"]["continues_beyond_junction"]:
        raise ValueError("Subject highway does not end at the junction")
    if not selected["other"]["continues_beyond_junction"]:
        raise ValueError("Other highway is not through at the junction")
    if selected["subject"]["highway_id"] == selected["other"]["highway_id"]:
        raise ValueError("Ending and through approaches share one highway identity")
    return selected


def _polygon(value, label):
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError("Missing original polygon: " + label)
    polygon = [(float(x), float(y)) for x, y in value]
    if any(not (isfinite(x) and isfinite(y)) for x, y in polygon):
        raise ValueError("Nonfinite original polygon: " + label)
    return polygon


def _overlap(a, b):
    """Convex-polygon separation test, including oriented Native body boxes."""
    for polygon in (a, b):
        for start, end in zip(polygon, polygon[1:] + polygon[:1]):
            dx, dy = end[0] - start[0], end[1] - start[1]
            if hypot(dx, dy) < 1e-6:
                raise ValueError("Degenerate original polygon edge")
            axis = -dy, dx
            left = [x * axis[0] + y * axis[1] for x, y in a]
            right = [x * axis[0] + y * axis[1] for x, y in b]
            if max(left) < min(right) or max(right) < min(left):
                return False
    return True


def measure(topology_path, frames_path):
    topology, topology_hash = _read(topology_path, "intersection_topology.json")
    roles = classify_approaches(topology)
    path = Path(frames_path)
    if not path.is_file():
        raise ValueError("Missing required source: intersection_participants.jsonl")
    raw = path.read_bytes()
    if not raw:
        raise ValueError("Empty required source: intersection_participants.jsonl")
    try:
        rows = [json.loads(line) for line in raw.splitlines()]
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("Invalid original intersection frames") from error
    if len(rows) < 3:
        raise ValueError("Intersection comparison needs approach, entry and exit frames")
    zone = _polygon(topology.get("conflict_polygon_xy"), "intersection conflict zone")
    subject_id, other_id = topology.get("subject_id"), topology.get("other_id")
    if not subject_id or not other_id or subject_id == other_id:
        raise ValueError("Topology lacks two distinct participant IDs")
    observations = []
    previous = None
    for row in rows:
        frame, time_s = row.get("frame"), row.get("time_s")
        if type(frame) is not int or type(time_s) not in (int, float):
            raise ValueError("Original frame/time identity missing")
        if not isfinite(time_s):
            raise ValueError("Nonfinite original intersection time")
        if previous is not None and (frame != previous[0] + 1 or
                                     abs(time_s - previous[1] - .05) > 1e-4):
            raise ValueError("Intersection original frames are not joined at 20 Hz")
        previous = frame, time_s
        if row.get("subject_id") != subject_id or row.get("other_id") != other_id:
            raise ValueError("Intersection participant identity changed")
        subject = _polygon(row.get("subject_corners"), "subject body")
        other = _polygon(row.get("other_corners"), "other body")
        observations.append({"frame": frame, "time_s": time_s,
                             "subject_in_conflict": _overlap(subject, zone),
                             "other_in_conflict": _overlap(other, zone)})
    def span(key):
        active = [r for r in observations if r[key]]
        if not active:
            raise ValueError("Participant never enters the intersection conflict zone: " + key)
        return active[0]["time_s"], active[-1]["time_s"], active[0]["frame"]
    subject_enter, subject_last, subject_frame = span("subject_in_conflict")
    other_enter, other_last, other_frame = span("other_in_conflict")
    return {"format": "worker-ending-road-observation", "topology_sha256": topology_hash,
            "frames_sha256": sha256(raw).hexdigest(), "approaches": roles,
            "subject_entry_frame": subject_frame, "other_entry_frame": other_frame,
            "entry_delta_s": subject_enter - other_enter,
            "subject_entered_after_other_last_conflict_frame": subject_enter > other_last,
            "conflict_overlap_observed": any(r["subject_in_conflict"] and r["other_in_conflict"]
                                             for r in observations),
            "observations": observations,
            "approximately_same_time_legal_judgment": None,
            "yield_right_of_way_legal_judgment": None}

"""Four synchronized original RGB source streams for ending-road probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-9, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown ending-road source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior intersection camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original ending-road camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("EndingRoad source encoder failed")


class EndingRoadCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named ending-road source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original ending-road camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original ending-road camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("EndingRoad source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original ending-road source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original ending-road camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Conservative Native control inventory for an ending/through route pair.

Landmarks are queried from both original approach lanes. A returned landmark is
treated as potentially governing until a later physical/source review resolves
its authority; an uncontrolled construction must reject that route pair.
"""


def approach_landmarks(path, *, lookahead_m=3.0):
    if not path or path[0].is_junction or not any(p.is_junction for p in path):
        raise ValueError('Control inventory requires an exterior-to-junction route')
    found = {}
    for waypoint in path:
        if waypoint.is_junction:
            break
        query = getattr(waypoint, 'get_landmarks', None)
        if query is None:
            raise ValueError('Native waypoint landmark query unavailable')
        for landmark in query(lookahead_m, stop_at_junction=True):
            ident = str(getattr(landmark, 'id', '') or '').strip()
            kind = str(getattr(landmark, 'type', '') or '').strip()
            if not ident or not kind:
                raise ValueError('Native landmark lacks OpenDRIVE ID or type')
            found[ident] = {'opendrive_id': ident, 'type': kind,
                            'approach_road_id': path[0].road_id,
                            'approach_lane_id': path[0].lane_id}
    return list(found.values())


def ungoverned_route_pair(ending, through, lights):
    """Fail closed on sign/landmark or traffic-light evidence at the junction."""
    from ending_road_device import devices_at_junction

    if devices_at_junction(lights, ending['junction_id']):
        return False
    return not (approach_landmarks(ending['path']) or
                approach_landmarks(through['path']))


def original_ungoverned_inventory(ending, through, lights):
    """Retain the selected Native no-control readback for later comparison.

    Both approach landmark queries and the junction light inventory are repeated
    after route selection, so a route predicate alone cannot stand in for a
    saved original source.
    """
    from ending_road_device import devices_at_junction

    junction_id = ending['junction_id']
    if through['junction_id'] != junction_id:
        raise ValueError('Control inventory routes enter different junctions')
    ending_marks = approach_landmarks(ending['path'])
    through_marks = approach_landmarks(through['path'])
    governing_lights = devices_at_junction(lights, junction_id)
    if ending_marks or through_marks or governing_lights:
        raise ValueError('Selected ordinary route has a potential governing control')
    return {'format': 'worker-ending-road-original-control-inventory',
            'junction_id': junction_id,
            'ending_approach_road_id': ending['path'][0].road_id,
            'ending_approach_lane_id': ending['path'][0].lane_id,
            'through_approach_road_id': through['path'][0].road_id,
            'through_approach_lane_id': through['path'][0].lane_id,
            'ending_landmarks': ending_marks, 'through_landmarks': through_marks,
            'junction_lights': [], 'legal_control_status_claimed': False}

